public int longestConsecutive(int[] nums) {
    Set<Integer> set = new HashSet<>();
    for (int x : nums) {
        set.add(x);
    }
    int best = 0;
    for (int x : set) {
        if (x != Integer.MIN_VALUE && set.contains(x - 1)) {
            continue;
        }
        int end = x;
        int length = 1;
        while (end != Integer.MAX_VALUE && set.contains(end + 1)) {
            end++;
            length++;
        }
        best = Math.max(best, length);
    }
    return best;
}

