public int networkDelayTime(int[][] times, int n, int k) {
    List<List<int[]>> graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : times) {
        graph.get(edge[0]).add(new int[]{edge[1], edge[2]});
    }
    long[] distance = new long[n + 1];
    Arrays.fill(distance, Long.MAX_VALUE);
    distance[k] = 0;
    PriorityQueue<long[]> heap = new PriorityQueue<>((a,b) -> Long.compare(a[0], b[0]));
    heap.offer(new long[]{0, k});
    while (!heap.isEmpty()) {
        long[] state = heap.poll();
        long d = state[0];
        int u = (int) state[1];
        if (d != distance[u]) {
            continue;
        }
        for (int[] edge : graph.get(u)) {
            long candidate = d + edge[1];
            if (candidate < distance[edge[0]]) {
                distance[edge[0]] = candidate;
                heap.offer(new long[]{candidate, edge[0]});
            }
        }
    }
    long answer = 0;
    for (int node = 1; node <= n; node++) {
        if (distance[node] == Long.MAX_VALUE) {
            return -1;
        }
        answer = Math.max(answer, distance[node]);
    }
    return (int) answer;
}

