    while (!heap.isEmpty()) {
        int[] state = heap.poll();
        int effort = state[0], r = state[1], c = state[2];
        if (effort != best[r][c]) {
            continue;
        }
        if (r == rows - 1 && c == cols - 1) {
            return effort;
        }
        for (int[] direction : directions) {
            int nr = r + direction[0], nc = c + direction[1];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }
            int candidate = Math.max(effort, Math.abs(heights[r][c] - heights[nr][nc]));
            if (candidate < best[nr][nc]) {
