public boolean canPartition(int[] nums) {
    int total = 0;
    for (int x : nums) {
        total += x;
    }
    if (total % 2 != 0) {
        return false;
    }
    int target = total / 2;
    boolean[] dp = new boolean[target + 1];
    dp[0] = true;
    for (int x : nums) {
        for (int sum = target; sum >= x; sum--) {
            dp[sum] = dp[sum] || dp[sum - x];
        }
    }
    return dp[target];
}

