public boolean exist(char[][] board, String word) {
    for (int r = 0; r < board.length; r++) {
        for (int c = 0; c < board[0].length; c++) {
            if (search(board, word, r, c, 0)) {
                return true;
            }
        }
    }
    return false;
}
private boolean search(char[][] board, String word, int r, int c, int i) {
    if (i == word.length()) {
        return true;
    }
    if (r < 0 || r >= board.length || c < 0 || c >= board[0].length || board[r][c] != word.charAt(i)) {
        return false;
    }
    char saved = board[r][c];
    board[r][c] = '#'; // Input contains letters only.
    boolean found = search(board, word, r + 1, c, i + 1)
        || search(board, word, r - 1, c, i + 1)
        || search(board, word, r, c + 1, i + 1)
        || search(board, word, r, c - 1, i + 1);
    board[r][c] = saved; // Restore even after success.
    return found;
}

